function sanitize_text_field($v){return trim(strip_tags($v));}
function sanitize_textarea_field($v){return trim(strip_tags($v));}
function kF(){return bin2hex(random_bytes(20));}
function okF($v,$m){if(!$v)throw new RuntimeException($m);echo "PASS: $m\n";}
function denyF($fn,$m){try{$fn();}catch(RuleViolation $e){okF(true,$m);return;}throw new RuntimeException($m);}
final class FakeStudentFiles implements StudentFiles {
 public array $saved=[];public bool $deletionFails=false;public bool $failRead=false;
 function put(array $f):array{$token=bin2hex(random_bytes(32));$bytes='PDF TEST CONTENT';$this->saved[$token]=$bytes;return ['arquivo_token'=>$token,'arquivo_nome'=>$f['name']??'documento.pdf','arquivo_mime'=>'application/pdf','tamanho'=>strlen($bytes),'sha256'=>hash('sha256',$bytes)];}
 function read(string $token):string{if($this->failRead||!isset($this->saved[$token]))throw new RuleViolation('Arquivo ausente');return $this->saved[$token];}
 function delete(string $token):bool{if($this->deletionFails)return false;unset($this->saved[$token]);return true;}
}
$db=new Database($wpdb);Access::install();$storage=new FakeStudentFiles();$docs=new StudentDocuments($db,$storage);$family=new FamilyStudents($db);
$child=$db->insert('pessoas',['nome'=>'ALUNO TESTE','data_nascimento'=>'2014-01-01','pais'=>'BR','estado'=>'PR','cidade'=>'CURITIBA','email'=>'aluno@example.test']);$student=$db->insert('alunos',['codpessoa'=>$child,'ra'=>'RA-01']);$studentUser=wp_insert_user(['user_login'=>'aluno.teste','user_email'=>'aluno@example.test','role'=>'erp_aluno']);$db->insert('pessoa_usuarios',['codpessoa'=>$child,'wp_user_id'=>$studentUser]);
$mother=$db->insert('pessoas',['nome'=>'MAE TESTE','data_nascimento'=>'1980-01-01']);$parent=wp_insert_user(['user_login'=>'mae.teste','role'=>'erp_responsavel_academico']);$db->insert('pessoa_usuarios',['codpessoa'=>$mother,'wp_user_id'=>$parent]);
$link=$db->insert('aluno_responsaveis',['idaluno'=>$student,'codpessoa_responsavel'=>$mother,'parentesco'=>'mae','responsavel_academico'=>1,'inicio_vigencia'=>'2020-01-01 00:00:00']);
$type=$docs->saveType(['nome'=>'Certidão de nascimento','orientacoes'=>'Envie uma imagem legível','obrigatorio'=>1],kF())['idtipo_documento'];
$staff=wp_insert_user(['user_login'=>'secretaria','role'=>'erp_secretaria']);$stranger=wp_insert_user(['user_login'=>'sem.vinculo','role'=>'erp_responsavel_academico']);
wp_set_current_user($parent);$detail=$family->detail($student);okF($detail['nome']==='ALUNO TESTE'&&!isset($detail['contato']['cpf'])&&!isset($detail['contato']['data_nascimento']),'responsável recebe somente identificação básica e contatos editáveis');
$change=['versao'=>$detail['versao'],'email'=>'novo.aluno@example.test','telefone'=>'41999999999','rua'=>'Rua nova','numero'=>'12','cep'=>'80010000'];$key=kF();$family->update($student,$change,$key);$family->update($student,$change,$key);okF($db->get('pessoas',$child)['rua']==='RUA NOVA'&&$db->get('pessoas',$child)['versao']==='2','contato normalizado e repetição idempotente sem novo incremento');
okF(get_userdata($studentUser)->user_email==='novo.aluno@example.test','alteração do e-mail também sincroniza a conta WordPress do aluno');
denyF(fn()=>$family->update($student,['versao'=>'2','nome'=>'Nome alterado'],kF()),'responsável não altera nome ou identificação do aluno');
