denyF(fn()=>$docs->saveType(['nome'=>'Tipo não permitido'],kF()),'responsável não cadastra tipos de documentos');
$listing=$docs->listing($student);okF(count($listing)===1&&$listing[0]['pode_enviar']&&!$listing[0]['documento'],'tipo configurado gera campo de upload do aluno');
$uploadKey=kF();$first=$docs->upload($student,$type,['name'=>'certidao.pdf'],$uploadKey);$again=$docs->upload($student,$type,['name'=>'certidao.pdf'],$uploadKey);okF($first===$again&&count($storage->saved)===1,'repetir upload não duplica arquivo nem envio');
$listing=$docs->listing($student);okF(!$listing[0]['pode_enviar']&&$listing[0]['documento']['status']==='pendente'&&!isset($listing[0]['documento']['arquivo_token']),'envio pendente bloqueia substituição e omite token privado');
denyF(fn()=>$docs->upload($student,$type,['name'=>'outro.pdf'],kF()),'novo pedido não substitui documento aguardando conferência');
denyF(fn()=>$docs->review($first['iddocumento'],['versao'=>'1','status'=>'aprovado'],kF()),'responsável não aprova o próprio documento');
wp_set_current_user($stranger);denyF(fn()=>$family->detail($student),'outro responsável não acessa aluno sem vínculo');denyF(fn()=>$docs->download($first['iddocumento']),'outro responsável não baixa arquivo alheio');
wp_set_current_user($staff);$savedPolicy=get_option('ederp_menu_policy',[]);update_option('ederp_menu_policy',['erp_secretaria'=>[]]);denyF(fn()=>$docs->queue('pendente',''),'revogação do menu bloqueia conferência mesmo com capability de pessoas');update_option('ederp_menu_policy',$savedPolicy);okF(count($docs->queue('pendente','ALUNO')['items'])===1,'secretaria encontra envio na fila de conferência');denyF(fn()=>$docs->review($first['iddocumento'],['versao'=>'1','status'=>'rejeitado','motivo'=>''],kF()),'rejeição exige motivo');
$storage->deletionFails=true;$rejectKey=kF();$docs->review($first['iddocumento'],['versao'=>'1','status'=>'rejeitado','motivo'=>'Documento ilegível'],$rejectKey);okF($db->get('aluno_documentos',$first['iddocumento'])['status']==='rejeitado'&&count($storage->saved)===1,'rejeição confirmada mantém tarefa de limpeza se disco falhar');
denyF(fn()=>$docs->download($first['iddocumento'],true),'arquivo rejeitado deixa de ser acessível mesmo antes da limpeza');$storage->deletionFails=false;$docs->cleanupRejected();okF(!$storage->saved&&$db->get('aluno_documentos',$first['iddocumento'])['arquivo_token']===null,'limpeza posterior exclui arquivo rejeitado e remove o token');
wp_set_current_user($parent);$listing=$docs->listing($student);okF($listing[0]['pode_enviar']&&$listing[0]['documento']['motivo']==='Documento ilegível','rejeição libera campo e mostra orientação para novo envio');
$second=$docs->upload($student,$type,['name'=>'certidao-legivel.pdf'],kF());wp_set_current_user($staff);$approveKey=kF();$docs->review($second['iddocumento'],['versao'=>'1','status'=>'aprovado'],$approveKey);$docs->review($second['iddocumento'],['versao'=>'1','status'=>'aprovado'],$approveKey);okF($db->get('aluno_documentos',$second['iddocumento'])['status']==='aprovado'&&count($storage->saved)===1,'aprovação preserva arquivo e é idempotente');
wp_set_current_user($parent);$listing=$docs->listing($student);okF(!$listing[0]['pode_enviar']&&$listing[0]['documento']['status']==='aprovado'&&base64_decode($docs->download($second['iddocumento'])['conteudo'])==='PDF TEST CONTENT','responsável vê aprovação e pode consultar documento aceito');
wp_set_current_user(1);denyF(fn()=>$docs->removeType($type,['versao'=>'1'],kF()),'tipo utilizado não é excluído para preservar histórico');$unused=$docs->saveType(['nome'=>'Documento opcional'],kF())['idtipo_documento'];$docs->removeType($unused,['versao'=>'1'],kF());okF(!$db->row('SELECT idtipo_documento FROM '.$db->table('tipos_documento_aluno').' WHERE idtipo_documento=%d',[$unused]),'tipo sem envios pode ser excluído');
$extraType=$docs->saveType(['nome'=>'Comprovante de endereço'],kF())['idtipo_documento'];wp_set_current_user($parent);$missing=$docs->upload($student,$extraType,['name'=>'endereco.pdf'],kF());wp_set_current_user($staff);$storage->failRead=true;denyF(fn()=>$docs->review($missing['iddocumento'],['versao'=>'1','status'=>'aprovado'],kF()),'arquivo indisponível não pode ser aprovado');okF($db->get('aluno_documentos',$missing['iddocumento'])['status']==='pendente','falha de leitura preserva estado pendente');$storage->failRead=false;$docs->review($missing['iddocumento'],['versao'=>'1','status'=>'rejeitado','motivo'=>'Envie novamente o comprovante'],kF());wp_set_current_user(1);$docs->saveType(['idtipo_documento'=>$extraType,'versao'=>'1','nome'=>'Comprovante de endereço','ativo'=>0],kF());
$company2=$db->insert('coligadas',['nome'=>'COLÉGIO 2','razao_social'=>'COLÉGIO 2']);$student2=$db->insert('alunos',['codcoligada'=>$company2,'codpessoa'=>$child,'ra'=>'RA-02']);$type2=Coligadas::within($company2,fn()=>$docs->saveType(['nome'=>'Carteira de vacinação'],kF()))['idtipo_documento'];
wp_set_current_user($parent);denyF(fn()=>$docs->upload($student,$type2,['name'=>'vacina.pdf'],kF()),'tipo de documento de outro colégio não é aceito');$db->insert('aluno_responsaveis',['codcoligada'=>$company2,'idaluno'=>$student2,'codpessoa_responsavel'=>$mother,'parentesco'=>'mae','responsavel_academico'=>1,'inicio_vigencia'=>'2020-01-01 00:00:00']);okF(count(array_filter($docs->listing($student),fn($r)=>$r['ativo']))===2,'família vê documentos dos colégios vinculados sem trocar de coligada');
$third=$docs->upload($student2,$type2,['name'=>'vacina.pdf'],kF());wp_set_current_user($staff);denyF(fn()=>$docs->download($third['iddocumento'],true),'secretaria não acessa documentos de outra coligada de trabalho');
wp_set_current_user(1);$db->update('aluno_responsaveis',$link,['fim_vigencia'=>'2025-01-01 00:00:00']);wp_set_current_user($parent);denyF(fn()=>$family->detail($student),'encerramento do vínculo revoga edição dos contatos');denyF(fn()=>$docs->download($second['iddocumento']),'encerramento do vínculo também revoga download do documento');
okF(count($db->rows('SELECT * FROM '.$db->table('auditoria')." WHERE acao IN ('contato_aluno_pelo_responsavel','enviar','conferir')"))>=6,'contatos, envios e conferências registram autor e data na auditoria');
